# -*- coding: utf-8 -*-
# Слайды pptx 57–61 (термины таблицы), тренажёр «Выбор маршрута», вопросы, финал.
from _rt_lib import *
from _rt_s1 import N, CL, E, T, PT, draw, pkt, on, off, add, rm, hl, scan, txt
