# ================================================================ 57–58. Термины таблицы маршрутизации
slide("Термины таблицы маршрутизации", head("Термины таблицы маршрутизации") + '<div class="two top">' +
      pn(P("Основная функция компьютерных сетей — организация взаимодействия между узлами, а для межсетевого взаимодействия нужен маршрутизатор. Прежде чем решать, куда отправлять пакеты, он создаёт таблицу маршрутизации — список маршрутов к известным сетям.",
           "Источники информации в таблице: <g>напрямую подключённые сети</g> и <g>удалённые сети</g>, сведения о которых получены статически (администратор вручную) или от протоколов динамической маршрутизации (RIP, OSPF, IS-IS, BGP).")) +
      con("esr# show ip route\n" + CODES + '''

S   * 10.10.20.0/24    [1/0]   via 203.0.113.2 on gi1/0/3   [static 19:16:44]
C   * 192.168.20.0/24  [0/0]   dev gi1/0/2                  [direct 18:38:51]
S   * 10.10.10.0/24    [1/0]   via 203.0.113.2 on gi1/0/3   [static 18:38:52]
C   * 192.168.10.0/24  [0/0]   dev gi1/0/1                  [direct 18:38:51]
C   * 203.0.113.0/24   [0/0]   dev gi1/0/3                  [direct 18:38:51]''', "Таблица маршрутизации R1") + '</div>')

slide("Иерархия таблицы", head("Термины таблицы маршрутизации", "Таблица — многоуровневая иерархическая база данных, оптимизированная для быстрого поиска", small=True) +
      pn(P("Таблица маршрутизации содержит большой и сложный объём данных о маршрутах к удалённым узлам. Каждый сетевой администратор должен уметь её читать. База данных делится на иерархические уровни:")) + grid(
    ncard(1, "содержит IP-адрес следующего перехода или выходной интерфейс", title="Окончательный маршрут"),
    ncard(2, "маска равна маске класса или меньше её", title="Маршрут 1-го уровня"),
    ncard(3, "классовый адрес, разделённый на подсети", title="Родительский маршрут 1-го уровня"),
    ncard(4, "подсеть классового сетевого адреса", title="Дочерний маршрут 2-го уровня", cls="teal"), cols="repeat(4,minmax(0,1fr))"))

# ================================================================ 59. Окончательный и 1-го уровня
def lvl_row(kind, net, cls=""):
    return (f'<div class="lvr {cls}" data-s="1"><span class="lk1">{kind}</span><span class="lk2">{net}</span><span class="lka">Окончательный маршрут</span>'
            f'<span class="lk3">Путь / интерфейс</span></div>')
slide("Окончательный маршрут", head("Термины таблицы маршрутизации", "Окончательный маршрут и маршрут 1-го уровня", small=True) + '<div class="two top">' + '<div class="col">' +
      '<div class="lvh" data-s="1"><span>Маршрут 1-го уровня</span><span>IP-адрес следующего перехода и/или выходной интерфейс</span></div>' +
      lvl_row("Сеть", "10.10.10.0/24") + lvl_row("Суперсеть", "10.10.0.0/16") + lvl_row("По умолчанию", "0.0.0.0/0") +
      pn(P("<g>Окончательный маршрут</g> — запись, содержащая IP-адрес следующего перехода или выходной интерфейс: напрямую подключённые сети, динамически получаемые маршруты.",
           "<g>Маршрут 1-го уровня</g> — маска равна маске класса или меньше: сетевой маршрут (маска равна классовой), маршрут суперсети (маска меньше классовой, например суммарный адрес), маршрут по умолчанию 0.0.0.0/0. Источник: прямая сеть, статический маршрут или протокол динамической маршрутизации.")) + '</div>' +
      con("R1# show ip route\n" + CODES + '''

S   * 0.0.0.0/0        [1/0]   via 203.0.113.2 on gi1/0/3   [static 00:15:07]
S   * 10.10.20.0/24    [1/0]   via 203.0.113.2 on gi1/0/3   [static 00:11:56]
C   * 192.168.20.0/24  [0/0]   dev gi1/0/2                  [direct 18:38:51]
S   * 10.10.10.0/24    [1/0]   via 203.0.113.2 on gi1/0/3   [static 18:38:52]
S   * 10.10.0.0/16     [1/0]   via 203.0.113.2 on gi1/0/3   [static 00:11:56]
C   * 192.168.10.0/24  [0/0]   dev gi1/0/1                  [direct 18:38:51]
C   * 203.0.113.0/24   [0/0]   dev gi1/0/3                  [direct 18:38:51]''', "Сеть, суперсеть и маршрут по умолчанию", hl=(9, 12, 13)) + '</div>')

# ================================================================ 60–61. Родительский и дочерний
slide("Родительский маршрут", head("Термины таблицы маршрутизации", "Родительский маршрут 1-го уровня", small=True) + '<div class="two top">' + '<div class="col">' +
      lvl_row("Сеть", "10.10.10.0/24") + lvl_row("Суперсеть", "10.10.0.0/16") + lvl_row("По умолчанию", "0.0.0.0/0") +
      '<div class="lvr par" data-s="1"><span class="lk1 o">Родительский: сеть</span><span class="lk2 v">Дочерний: подсеть</span><span class="lka">Окончательный маршрут</span><span class="lk3">Путь / интерфейс</span></div>' +
      '<div class="gr" style="grid-template-columns:repeat(2,minmax(0,1fr))">' +
      '<div class="pn lvx" data-s="1"><b class="gd">10.20.0.0/16</b><span>10.20.1.0/24 · 10.20.40.0/24 · 10.20.70.0/24</span></div>'.replace(" · ", "<br>") +
      '<div class="pn lvx teal" data-s="1"><b class="tl">210.7.222.0</b><span>210.7.222.1/30<br>210.7.222.5/30<br>210.7.222.9/30<br>210.7.222.13/30</span></div></div></div>' +
      '<div class="col">' + pn(P("<g>Родительский маршрут 1-го уровня</g> — маршрут, разделённый на подсети. Это классовый сетевой адрес; он отражает число подсетей и число разных масок, на которые поделён классовый адрес.")) +
      icard("warn", "Родительский маршрут 1-го уровня <g>не может быть окончательным</g>: в нём нет ни следующего перехода, ни выходного интерфейса — только ссылки на дочерние подсети.", "Важно", teal=True) + '</div></div>')

slide("Дочерний маршрут", head("Термины таблицы маршрутизации", "Дочерний маршрут 2-го уровня", small=True) + '<div class="two top">' +
      con("R1# show ip route\n" + CODES + '''

S   * 0.0.0.0/0        [1/0]   via 203.0.113.2 on gi1/0/3   [static 00:31:22]
S   * 10.20.20.0/24    [1/0]   via 203.0.113.2 on gi1/0/3   [static 00:31:22]
C   * 210.7.222.4/30   [0/0]   dev gi1/0/5                  [direct 00:40:18]
S   * 10.20.40.0/24    [1/0]   via 210.7.222.2 on gi1/0/4   [static 00:32:44]
C   * 192.168.20.0/24  [0/0]   dev gi1/0/2                  [direct 18:38:51]
C   * 210.7.222.8/30   [0/0]   dev gi1/0/6                  [direct 00:40:18]
S   * 10.10.10.0/24    [1/0]   via 203.0.113.2 on gi1/0/3   [static 00:31:22]
S   * 10.20.70.0/24    [1/0]   via 210.7.222.2 on gi1/0/4   [static 00:32:44]
S   * 10.10.0.0/16     [1/0]   via 203.0.113.2 on gi1/0/3   [static 00:31:22]
C   * 192.168.10.0/24  [0/0]   dev gi1/0/1                  [direct 18:38:51]
C   * 210.7.222.12/30  [0/0]   dev gi1/0/7                  [direct 00:40:18]
C   * 210.7.222.0/30   [0/0]   dev gi1/0/4                  [direct 00:32:44]
C   * 203.0.113.0/24   [0/0]   dev gi1/0/3                  [direct 00:31:22]''', "Дочерние подсети 10.20.0.0 и 210.7.222.0", hl=(11, 13, 15, 16, 18, 20, 21)) + '<div class="col">' +
      pn(P("<g>Дочерний маршрут 2-го уровня</g> — подсеть классового сетевого адреса. Родительский маршрут 1-го уровня, разделённый на подсети, содержит дочерние маршруты 2-го уровня.",
           "Источник дочернего маршрута — напрямую подключённая сеть, статический или динамический маршрут. Дочерние маршруты 2-го уровня <g>являются окончательными</g>: в них есть следующий переход или выходной интерфейс.")) +
      grid(icard("tree", "10.20.20.0/24, 10.20.40.0/24, 10.20.70.0/24 — подсети 10.20.0.0", "Статические"),
           icard("link", "210.7.222.0/30, .4/30, .8/30, .12/30 — подсети 210.7.222.0", "Прямые", teal=True), cols="minmax(0,1fr)") + '</div></div>')

# ================================================================ Тренажёр «Выбор маршрута»
TR_ROWS = [("C", "192.168.1.0/24", "напрямую", "gi1/0/1", "LAN"), ("S", "10.0.0.0/8", "172.16.12.2", "gi1/0/2", "R2"),
           ("S", "10.20.0.0/16", "172.16.13.2", "gi1/0/3", "R3"), ("S", "10.20.30.0/24", "172.16.14.2", "gi1/0/4", "R4"),
           ("S", "172.20.0.0/16", "172.16.13.2", "gi1/0/3", "R3"), ("S", "0.0.0.0/0", "172.16.15.2", "gi1/0/5", "R5")]
topo("ttr", {"vb": [760, 470], "al": "R1 и соседние маршрутизаторы R2–R5, локальная сеть 192.168.1.0/24", "nohint": 1,
             "n": [CL("LAN", 95, 235, 170, 100, "LAN", l2="192.168.1.0/24"), N("R1", "r", 330, 235, "R1", "b"), N("R2", "r", 560, 70, "R2", "r"),
                   N("R3", "r", 650, 205, "R3", "r"), N("R4", "r", 610, 345, "R4", "r"), N("R5", "r", 360, 420, "R5", "r"),
                   CL("NET2", 560, 20, 130, 44, "10.0.0.0/8", z=13), CL("NET4", 700, 420, 150, 44, "10.20.30.0/24", z=13)],
             "e": [E("LAN", "R1"), E("R1", "R2"), E("R1", "R3"), E("R1", "R4"), E("R1", "R5")],
             "tx": [T(470, 140, ".12.2", "g", z=13), T(500, 212, ".13.2", "g", z=13), T(480, 300, ".14.2", "g", z=13), T(318, 340, ".15.2", "g", "end", 13),
                    T(360, 462, "Интернет (по умолчанию)", "dm", z=13), T(700, 245, "10.20.0.0/16, 172.20.0.0/16", "dm", "end", 12)],
             "p": [PT("LAN", ["R1", "LAN"]), PT("R2", ["R1", "R2"]), PT("R3", ["R1", "R3"]), PT("R4", ["R1", "R4"]), PT("R5", ["R1", "R5"])], "pk": []})
trt = table("Таблица маршрутизации R1", ["Код", "Сеть назначения", "Следующий переход", "Интерфейс"], [list(r[:4]) for r in TR_ROWS], tid="trt")
slide("Тренажёр: выбор маршрута", head("Тренажёр: выбор маршрута", "Введите адрес назначения или найдите строку сами — правило самого длинного совпадения", small=True) +
      f'''<div class="two top trn" id="trn"><div class="col"><div class="topo" data-s="1" data-topo="ttr"></div></div>
<div class="col">{trt}
<div class="pn" data-s="1"><div class="row"><button type="button" class="btn on" data-m="show">Показать решение</button><button type="button" class="btn" data-m="self">Сам найди строку</button></div>
<div class="row" style="margin-top:.6rem"><label for="trip">IP назначения</label><input id="trip" value="10.20.30.77" inputmode="decimal" autocomplete="off" spellcheck="false">
<button type="button" class="btn" id="trgo">Проверить</button><button type="button" class="btn" id="trnew">Другое условие</button></div>
<div class="msg" id="trmsg" aria-live="polite"></div></div></div></div>''')

# ================================================================ Проверь себя
slide("Проверь себя: 1", head("Проверь себя", "Нажмите на вопрос, чтобы увидеть ответ") + grid(
    qa("Чем маршрут с прямым подключением отличается от удалённого?", "Прямой маршрут появляется автоматически, когда интерфейс настроен и в состоянии up/up; следующего перехода у него нет. Удалённый ведёт к сети за другим маршрутизатором и задаётся статически или протоколом динамической маршрутизации."),
    qa("Что сделает маршрутизатор, если подходящего маршрута нет?", "Проверит маршрут по умолчанию 0.0.0.0/0. Если его нет — пакет отбрасывается."),
    qa("В таблице есть 172.16.0.0/12, 172.16.0.0/18 и 172.16.0.0/26. Куда уйдёт пакет для 172.16.0.10?", "По 172.16.0.0/26: это самое длинное совпадение."),
    qa("Статический маршрут и RIP ведут в одну сеть с одинаковой маской. Какой попадёт в таблицу?", "Статический: у него preference 1, у RIP — 100. Меньшее значение — выше приоритет."),
    qa("Как RIP и OSPF считают метрику?", "RIP — количество переходов (максимум 15, 16 — недоступно). OSPF — сумма стоимостей интерфейсов с учётом полосы пропускания."),
    qa("Что меняется в кадре при прохождении маршрутизатора, а что нет?", "Меняются MAC-адреса источника и назначения (новая инкапсуляция), уменьшается TTL. IP-адреса источника и назначения остаются прежними."),
    cols="repeat(2,minmax(0,1fr))"))

slide("Проверь себя: 2", head("Проверь себя", "Команды и термины") + grid(
    qa("Чем RIB отличается от FIB?", "RIB хранит все маршруты из всех источников, в том числе несколько к одной сети (show ip route all). FIB — только лучшие маршруты; по ней и пересылаются пакеты (show ip route)."),
    qa("Что такое плавающий статический маршрут?", "Резервный статический маршрут с большей метрикой (например, 10). Он становится активным, только когда основной недоступен."),
    qa("Что означает запись [1/10] в выводе show ip route?", "1 — preference источника маршрута, 10 — стоимость (cost)."),
    qa("Что такое рекурсивный поиск?", "Если в маршруте указан только адрес следующего перехода, маршрутизатор повторно ищет в таблице маршрут к этому адресу, чтобы определить выходной интерфейс."),
    qa("Как настроить маршрут к 192.168.20.0/24 через 203.0.113.2 на ESR?", "<c>R1(config)# ip route 192.168.20.0/24 203.0.113.2</c>"),
    qa("Почему родительский маршрут 1-го уровня не бывает окончательным?", "В нём нет следующего перехода или выходного интерфейса: он только объединяет дочерние подсети классового адреса."),
    cols="repeat(2,minmax(0,1fr))"))

# ================================================================ Финал
slide("Спасибо за внимание", '''
<p class="kick" data-s="1">Маршрутизация и типы маршрутизации</p>
<h1 data-s="1">Спасибо<br>за внимание</h1>
<div class="orn" data-s="1" aria-hidden="true"><i></i><b></b><i></i></div>''' + grid(
    icard("table", "Прямые сети появляются сами, удалённые — статически или динамически", "Таблица"),
    icard("search", "Самое длинное совпадение, затем preference, затем cost", "Выбор"),
    icard("route", "IP неизменны, MAC меняются на каждом участке", "Пересылка", teal=True), cols="repeat(3,minmax(0,1fr))") +
      '<div class="au" data-s="1"><span>Ананко Софья Михайловна</span><span>Качур Анна Юрьевна</span></div>', "title")
